const LogoTextFreeClause = "Render a text-free mark: a single pictorial symbol, one composition on one plain background, containing no lettering, words, letters, numerals or typography of any kind. The brand name is set in HTML beside the logo and must never be painted into the image. This instruction overrides any earlier wording in this prompt that mentions, permits or presupposes a wordmark or any text."

const LogoTextFreeSentinel = "Render a text-free mark"

func LogoWordmarkClause(text string) string {
	return fmt.Sprintf("The only text in the image is the exact wordmark %q, spelled exactly as written, rendered once, as a single composition on one plain background; no other lettering, words or numerals anywhere. This instruction overrides any earlier wording in this prompt about text.", text)
}

// in composeBrandImagePrompt's logo branch, replacing the inline no-lettering sentence:
b.WriteString(" Flat vector mark, minimal and geometric, a single clear silhouette that stays legible at favicon size, centred on a plain background, no photographic texture, no drop shadows.")
b.WriteString(" " + LogoTextFreeClause)

type imageKind struct {
	Kind, Signal string
	Answered     bool   // did ANY source identify it, even as a non-logo?
	Conflict     string // a STATED kind the step's own name contradicts
}

func stepNameKindHint(name string) string {
	n := strings.ToLower(name)
	hasLogo, hasHero := strings.Contains(n, "logo"), strings.Contains(n, "hero")
	if hasLogo == hasHero { return "" }  // neither, or BOTH (check_logo_or_hero) — abstain
	if hasLogo { return "logo" }
	return "hero"
}

func resolveKind(inputData, agentConfig map[string]interface{}, step models.Step) imageKind {
	stated := func(k, signal string) (imageKind, bool) {
		if k == "" { return imageKind{}, false }
		r := imageKind{Kind: k, Signal: signal, Answered: true}
		if hint := stepNameKindHint(step.Name); hint != "" && hint != k {
			r.Conflict = fmt.Sprintf("step %q implies kind %q but the caller stated %q", step.Name, hint, k)
		}
		return r, true
	}
	// kind, default_kind, purpose, spec.purpose, step.Config[purpose|kind], then step name
	if k, ok := inputData["kind"].(string); ok { if r, done := stated(k, "kind"); done { return r } }
	// … the remaining sources, same shape …
	if step.Config != nil {
		if p, ok := step.Config["purpose"].(string); ok { if r, done := stated(p, "step_purpose"); done { return r } }
		if k, ok := step.Config["kind"].(string); ok { if r, done := stated(k, "step_kind"); done { return r } }
	}
	if hint := stepNameKindHint(step.Name); hint != "" {
		return imageKind{Kind: hint, Signal: "step_name", Answered: true}
	}
	return imageKind{}
}

// at the call site:
kindRes := resolveKind(inputData, agentConfig, params.StepConfig)
kind := kindRes.Kind
if kind == "logo" { /* policy; promptSource += "+via_" + kindRes.Signal */ }
if !kindRes.Answered {
	recordImagePolicyEvent(ctx, params, siteID, "image_generation_without_kind", "warning", ...)
} else if kindRes.Conflict != "" {
	recordImagePolicyEvent(ctx, params, siteID, "image_kind_conflict", "warning", ...)
}

func recordImagePolicyEvent(ctx context.Context, params ActionParams, siteID, code, severity, message string, context map[string]interface{}) {
	LogActionEntryInheritingProvenance(ctx, params, agenterrors.Entry{
		SiteID: siteID, AgentType: params.AgentType, StepName: params.StepConfig.Name,
		Action: "generate_image", ErrorCode: code, Severity: severity,
		ErrorMessage: message, Context: context,
	}, params.Logger)
}

func TestLogoTextPolicyDefaultAppendsTextFreeClause(t *testing.T) {
	got, neg, src := applyLogoTextPolicy(boxingPrompt, "people, faces, signature, watermark", "site_plan", "", logoIdentity{}, zap.NewNop())
	// clause appended; ORIGINAL prompt preserved verbatim (the clause overrides,
	// it does not rewrite, so the wording stays auditable in origin_prompt);
	// source tagged; negatives gain text/lettering/words
}

func TestLogoTextPolicyRejectsAWordmarkThatIsNotThisSitesName(t *testing.T) {
	ident := logoIdentity{CompanyName: "Boxing Online", Domain: "boxingonline.com"}
	got, _, src := applyLogoTextPolicy("A bold logomark.", "", "site_plan", "Farm Shield Info", ident, zap.NewNop())
	// the invented string must NOT reach the prompt; must DEGRADE to text-free, not refuse
}

func TestLogoFallbackPromptCarriesTheSharedTextRule(t *testing.T) {
	got := composeBrandImagePrompt(siteBrandFacts{Name: "Boxing Online", Domain: "boxingonline.com"}, "logo")
	if !strings.Contains(got, LogoTextFreeClause) {
		t.Fatalf("the two prompt paths have drifted, which is bugs_open/417's mechanism")
	}
}

UPDATE site_plan_imagery spi SET prompt = prompt || ' — OWNER RULING 2026-08-31 (migration 680, race tail of 670): render a text-free mark ...'
 FROM site_plans sp
 WHERE sp.id = spi.plan_id AND spi.id = 'b56182fa-...' AND spi.kind='logo'
   AND sp.is_current AND spi.locked_at IS NULL
   AND spi.prompt LIKE '%no text other than the wordmark itself%'
   AND spi.prompt NOT LIKE '%migration 6%';
GET DIAGNOSTICS v_n = ROW_COUNT;
IF v_n <> 1 THEN RAISE EXCEPTION '680: expected exactly 1 race-tail row, updated % ...', v_n; END IF;
